-- ---------------------------------------------------------------------------
-- 9. Postflight: the migration proves its own counts, or it does not apply
-- ---------------------------------------------------------------------------
DO $post$
DECLARE _n integer;
BEGIN
  SELECT count(*) INTO _n FROM public.sp_catalogue_research_records WHERE snapshot_date = DATE '2026-10-03';
  IF _n <> 170 THEN RAISE EXCEPTION 'SP_RESEARCH_IMPORT_COUNT: expected 170 research records, found %', _n; END IF;
  SELECT count(*) INTO _n FROM public.sp_catalogue_research_records WHERE reconciliation_outcome = 'matched_existing';
  IF _n <> 14 THEN RAISE EXCEPTION 'SP_RESEARCH_IMPORT_OUTCOME: expected 14 matched_existing, found %', _n; END IF;
  SELECT count(*) INTO _n FROM public.sp_catalogue_research_records WHERE reconciliation_outcome = 'added_approved';
  IF _n <> 140 THEN RAISE EXCEPTION 'SP_RESEARCH_IMPORT_OUTCOME: expected 140 added_approved, found %', _n; END IF;
  SELECT count(*) INTO _n FROM public.sp_catalogue_research_records WHERE reconciliation_outcome = 'retained_for_review';
  IF _n <> 16 THEN RAISE EXCEPTION 'SP_RESEARCH_IMPORT_OUTCOME: expected 16 retained_for_review, found %', _n; END IF;
  SELECT count(*) INTO _n FROM public.sp_catalogue_research_records WHERE reconciliation_outcome = 'excluded';
  IF _n <> 0 THEN RAISE EXCEPTION 'SP_RESEARCH_IMPORT_OUTCOME: expected 0 excluded, found %', _n; END IF;
  SELECT count(*) INTO _n FROM public.sp_credential_types t
    JOIN public.sp_catalogue_research_records r ON r.credential_code = t.code
    WHERE r.reconciliation_outcome = 'added_approved'
      AND (t.is_active OR t.scope_code IS DISTINCT FROM 'global_professional'
           OR t.jurisdiction_code IS NOT NULL OR t.market_pack_code IS NOT NULL
           OR t.allows_no_expiry OR t.legal_review_state <> 'pending');
  IF _n <> 0 THEN RAISE EXCEPTION 'SP_RESEARCH_IMPORT_NOT_INERT: % new definitions are active, scoped to a place, or allow no expiry', _n; END IF;
  SELECT count(*) INTO _n FROM public.sp_credential_types WHERE code LIKE 'INTL\_%' AND is_active;
  IF _n <> 14 THEN RAISE EXCEPTION 'SP_RESEARCH_IMPORT_ACTIVATED: expected 14 active international definitions, found %', _n; END IF;
END $post$;

COMMIT;
